(async () => {
  for (let i = 0; i < 200 && !state.results.length; i++) await new Promise((r) => setTimeout(r, 100));
  const bad = [];
  const sq = [
    ['Qwen 3.8 27B Uncensored Q4_K_M', 'Qwen 3.8 27B Uncensored', 'Q4_K_M'],
    ['Q4_K_M', 'Q4_K_M', 'Q4_K_M'],
    ['unsloth UD-Q4_K_XL', 'unsloth', 'Q4_K_XL'],
    ['Qwen3.8-27B-Uncensored-Q4_K_M.gguf', 'Qwen3.8-27B-Uncensored', 'Q4_K_M'],
    ['Qwen3.8-27B-Uncensored-FP8-Q4_K_M-GGUF', 'Qwen3.8-27B-Uncensored-FP8 GGUF', 'Q4_K_M'],
    ['gemma-3-27b-it-UD-Q4_K_XL-00001-of-00002.gguf', 'gemma-3-27b-it', 'Q4_K_XL'],
    ['qwen3 14b', 'qwen3 14b', ''],
    ['orcarouter q4_k_m', 'orcarouter', 'Q4_K_M'],
    ['Q8_0 qwen', 'qwen', 'Q8_0'],
    ['gpt-oss mxfp4', 'gpt-oss', 'MXFP4'],
    ['llama3.2 iq4_xs', 'llama3.2', 'IQ4_XS'],
    ['qwen3-coder', 'qwen3-coder', ''],
    ['model.gguf', 'model.gguf', ''],
  ];
  for (const [inp, text, quant] of sq) { const r = splitQuant(inp); if (r.text !== text || r.quant !== quant) bad.push('splitQuant(' + inp + ') = ' + JSON.stringify(r)); }
  const ol = [
    ['https://ollama.com/orcarouter/Qwen3.8-27B-Uncensored:q4_K_M', { ns: 'orcarouter', text: 'Qwen3.8-27B-Uncensored Q4_K_M', quant: 'Q4_K_M' }],
    ['ollama.com/orcarouter/Qwen3.8-27B-Uncensored:q4_K_M', { ns: 'orcarouter', text: 'Qwen3.8-27B-Uncensored Q4_K_M', quant: 'Q4_K_M' }],
    ['ollama run orcarouter/Qwen3.8-27B-Uncensored:q4_K_M', { ns: 'orcarouter', text: 'Qwen3.8-27B-Uncensored Q4_K_M', quant: 'Q4_K_M' }],
    ['orcarouter/Qwen3.8-27B-Uncensored:q4_K_M', { ns: 'orcarouter', text: 'Qwen3.8-27B-Uncensored Q4_K_M', quant: 'Q4_K_M' }],
    ['ollama pull qwen3:32b', { ns: '', text: 'qwen 3 32b', quant: '' }],
    ['https://ollama.com/library/llama3.2:3b-instruct-q8_0', { ns: '', text: 'llama 3.2 3b instruct Q8_0', quant: 'Q8_0' }],
    ['https://ollama.com/library/gemma3:latest', { ns: '', text: 'gemma 3', quant: '' }],
    ['https://ollama.com/library/deepseek-r1', { ns: '', text: 'deepseek r1', quant: '' }],
    ['registry.ollama.ai/library/qwen3:14b', { ns: '', text: 'qwen 3 14b', quant: '' }],
    ['https://ollama.com/orcarouter', { ns: '', text: 'orcarouter', quant: '' }],
    ['ollama run hf.co/bartowski/Qwen_Qwen3-14B-GGUF:Q4_K_M', { repo: 'bartowski/Qwen_Qwen3-14B-GGUF', quant: 'Q4_K_M' }],
    ['hf.co/unsloth/gpt-oss-20b-GGUF', { repo: 'unsloth/gpt-oss-20b-GGUF', quant: '' }],
    ['https://ollama.com/unsloth/gemma-3-27b-it:UD-Q4_K_XL', { ns: 'unsloth', text: 'gemma-3-27b-it Q4_K_XL', quant: 'Q4_K_XL' }],
    ['https://ollama.com/blog/llama-3', null],
    ['https://ollama.com/library', null],
    ['https://ollama.com/search?q=qwen', null],
    ['https://huggingface.co/Qwen/Qwen3-14B', null],
    ['Qwen/Qwen3-14B', null],
    ['qwen3 14b', null],
  ];
  for (const [inp, want] of ol) {
    const r = parseOllama(inp);
    if (want === null) { if (r !== null) bad.push('parseOllama(' + inp + ') should be null, is ' + JSON.stringify(r)); continue; }
    if (!r) { bad.push('parseOllama(' + inp + ') = null'); continue; }
    for (const k of Object.keys(want)) if (r[k] !== want[k]) bad.push('parseOllama(' + inp + ').' + k + ' = ' + JSON.stringify(r[k]) + ', want ' + JSON.stringify(want[k]));
  }
  if (hfRepoId('https://huggingface.co/Qwen/Qwen3-14B') !== 'Qwen/Qwen3-14B') bad.push('hfRepoId changed');
  const fq = [['Qwen3.8-27B-Uncensored-Q4_K_M.gguf', 'Q4_K_M', true], ['gemma-3-27b-it-UD-Q4_K_XL-00001-of-00002.gguf', 'Q4_K_XL', true], ['gemma-3-27b-it-UD-Q4_K_XL.gguf', 'Q4_K', false], ['sub/model.Q8_0.gguf', 'Q8_0', true], ['Qwen3.8-27B-Uncensored-Q4_K_S.gguf', 'Q4_K_M', false]];
  for (const [p, q, want] of fq) if (fileHasQuant(p, q) !== want) bad.push('fileHasQuant(' + p + ', ' + q + ') = ' + !want);
  return bad.length ? 'FAIL ' + bad.length + ': ' + bad.join(' | ') : (sq.length + ol.length + fq.length + 1) + ' parser cases OK';
})()

(async () => {
  const q = document.getElementById('q');
  q.value = 'qwen3 14b Q4_K_M'; q.dispatchEvent(new Event('input', { bubbles: true }));
  await new Promise((r) => setTimeout(r, 400));
  const bar = document.getElementById('searchBar').innerText;
  const bad = [];
  if (searchText() !== 'qwen3 14b') bad.push('searchText ' + JSON.stringify(searchText()));
  if (markedQuant(state.selected) !== 'Q4_K_M') bad.push('marked quant ' + markedQuant(state.selected));
  if (!/Left out Q4_K_M/.test(bar)) bad.push('no Left out line: ' + bar.slice(0, 200));
  if (!/Search Hugging Face for "qwen3 14b"/.test(bar)) bad.push('button text: ' + bar.slice(0, 200));
  if (!state.visible.length) bad.push('no rows match qwen3 14b');
  return bad.length ? 'FAIL: ' + bad.join(' | ') : state.visible.length + ' rows match | bar: ' + bar.replace(/\s+/g, ' ').slice(0, 260);
})()

(async () => {
  const id = state.visible[0].m.id; showModel(id, 'overview');
  for (let i = 0; i < 100 && !document.querySelector('#detail table.ladder'); i++) await new Promise((r) => setTimeout(r, 100));
  const rows = [...document.querySelectorAll('#detail table.ladder tbody tr')].filter((tr) => tr.querySelector('.tag.searched'));
  const txt = rows.map((tr) => tr.querySelector('td').innerText.replace(/\s+/g, ' ').trim());
  return rows.length === 1 && /^Q4_K_M you searched$/.test(txt[0]) ? id + ' | marked row: ' + txt[0] + ' | colour ' + getComputedStyle(rows[0].querySelector('.tag.searched')).color : 'FAIL: marked rows ' + JSON.stringify(txt);
})()

