(async () => {
  const q = document.getElementById('q'), bad = [], calls = [];
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const paste = async (v) => { q.value = v; q.dispatchEvent(new Event('input', { bubbles: true })); await sleep(400); };
  const enter = async () => { q.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await sleep(300); };
  // Offline: the two live calls are stand-ins that record their arguments (checkHfLink clears the box, as the real one does).
  const orig = { hub: searchHub, check: checkHfLink };
  searchHub = async (t, o) => { calls.push(['hub', t, o && o.from, o && o.author, o && o.name].join(' | ')); };
  checkHfLink = async (id) => { calls.push('check | ' + id); state.search = ''; q.value = ''; renderList(); };
  try {
    await paste('https://ollama.com/orcarouter/Qwen3.8-27B-Uncensored:q4_K_M');
    const hint = document.getElementById('searchBar').innerText.replace(/\s+/g, ' ');
    if (!/Press Enter to look for orcarouter\/Qwen3.8-27B-Uncensored:q4_K_M on Hugging Face by name/.test(hint)) bad.push('hint: ' + hint.slice(0, 200));
    if (searchText() !== '') bad.push('link filters the list: ' + searchText());
    await enter();
    if (q.value !== 'Qwen3.8-27B-Uncensored Q4_K_M') bad.push('field after Enter: ' + q.value);
    if (calls[0] !== 'hub | Qwen3.8-27B-Uncensored Q4_K_M | orcarouter/Qwen3.8-27B-Uncensored:q4_K_M | orcarouter | Qwen3.8-27B-Uncensored') bad.push('search call: ' + calls[0]);
    if (markedQuant('any/model') !== 'Q4_K_M') bad.push('search mark ' + markedQuant('any/model'));
    await paste('ollama run hf.co/bartowski/Qwen_Qwen3-14B-GGUF:Q6_K');
    await enter();
    if (calls[1] !== 'check | bartowski/Qwen_Qwen3-14B-GGUF') bad.push('hf.co call: ' + calls[1]);
    if (markedQuant('bartowski/Qwen_Qwen3-14B-GGUF') !== 'Q6_K') bad.push('hf.co mark lost after the box was cleared: ' + markedQuant('bartowski/Qwen_Qwen3-14B-GGUF'));
    if (markedQuant('Qwen/Qwen3-14B')) bad.push('another model is marked too: ' + markedQuant('Qwen/Qwen3-14B'));
    const was = state.liveBusy; state.liveBusy = true;
    await paste('https://ollama.com/library/qwen3:14b');
    await enter();
    state.liveBusy = was;
    if (q.value !== 'https://ollama.com/library/qwen3:14b' || calls.length !== 2) bad.push('busy: box ' + q.value + ', calls ' + calls.length);
    await paste('qwen3');
    if (markedQuant('bartowski/Qwen_Qwen3-14B-GGUF')) bad.push('mark stays after typing: ' + markedQuant('bartowski/Qwen_Qwen3-14B-GGUF'));
    await paste('');
  } finally { searchHub = orig.hub; checkHfLink = orig.check; }
  return bad.length ? 'FAIL: ' + bad.join(' | ') : 'Ollama link: hint, search call and mark OK; hf.co: check call, mark on that model only, also after the box is cleared; busy: box kept; typing ends the mark';
})()
